<div class="settings-section">
    <h3>Notifications</h3>
    <p class="text-muted">Configure how you receive notifications</p>
    <hr />

    <div class="mb-4">
        <h5>General</h5>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif"
                   checked="@EmailNotifications" @onchange="e => EmailNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif"
                   checked="@PushNotifications" @onchange="e => PushNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest"
                   checked="@WeeklyDigest" @onchange="e => WeeklyDigest = (bool)e.Value!" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h5>Muted Channels</h5>
        <p class="text-muted small">Uncheck channels to unmute them</p>
        @if (AllChannels.Count > 0)
        {
            @foreach (var channel in AllChannels)
            {
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@MutedSet.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">
                        # @channel
                    </label>
                </div>
            }
        }
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>

    @if (!string.IsNullOrEmpty(_statusMessage))
    {
        <div class="alert alert-success mt-3">@_statusMessage</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private HashSet<string> MutedSet { get; set; } = new();
    private List<string> AllChannels { get; set; } = new();

    private string _statusMessage = "";

    protected override void OnParametersSet()
    {
        if (Prefs is null) return;
        EmailNotifications = Prefs.EmailNotifications;
        PushNotifications = Prefs.PushNotifications;
        WeeklyDigest = Prefs.WeeklyDigest;
        AllChannels = new List<string>(Prefs.MutedChannels);
        MutedSet = new HashSet<string>(Prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            MutedSet.Add(channel);
        else
            MutedSet.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(
            EmailNotifications, PushNotifications, WeeklyDigest,
            MutedSet.ToList());
        await OnSave.InvokeAsync(updated);
        _statusMessage = "✓ Preferences saved!";
    }
}
