@using sv_6fe0a396bb4c423c9792946e8aecb099.Models

<div class="settings-section">
    <h3>Appearance</h3>
    <p class="text-muted">Customize how the application looks</p>
    <hr />

    <div class="row">
        <div class="col-md-6">
            @* Theme Selector *@
            <div class="mb-4">
                <h5>Theme</h5>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme}")" value="@theme"
                               checked="@(SelectedTheme == theme)"
                               @onchange="() => SelectedTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            @* Font Size *@
            <div class="mb-4">
                <h5>Font Size</h5>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"fs-{size}")" value="@size"
                               checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            @* Language *@
            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select" @bind="SelectedLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            @* Compact Mode *@
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@CompactMode"
                           @onchange="e => CompactMode = (bool)e.Value!" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert alert-success mt-3">@_statusMessage</div>
            }
        </div>

        @* Live Preview *@
        <div class="col-md-6">
            <h5>Preview</h5>
            <div class="appearance-preview @PreviewThemeClass" style="@PreviewFontStyle">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                </div>
                <div class="preview-body" style="@(CompactMode ? "padding:0.5rem;" : "padding:1rem;")">
                    <p class="preview-text">This is a preview of your selected appearance settings.</p>
                    <div class="preview-card">
                        <span class="preview-label">Theme:</span> @SelectedTheme
                    </div>
                    <div class="preview-card">
                        <span class="preview-label">Font:</span> @SelectedFontSize
                    </div>
                    <div class="preview-card">
                        <span class="preview-label">Language:</span> @SelectedLanguage
                    </div>
                    <div class="preview-card">
                        <span class="preview-label">Compact:</span> @(CompactMode ? "On" : "Off")
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings Settings { get; set; } = default!;

    [Parameter]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private string _statusMessage = "";

    protected override void OnParametersSet()
    {
        if (Settings is null) return;
        SelectedTheme = Settings.Theme;
        SelectedFontSize = Settings.FontSize;
        SelectedLanguage = Settings.Language;
        CompactMode = Settings.CompactMode;
    }

    private string PreviewThemeClass => SelectedTheme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => SelectedFontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.15rem;",
        _ => "font-size:1rem;"
    };

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "✓ Appearance saved!";
    }
}

